SET search_path = commerce, public;

-- Org settings: the approval threshold. NULL = no threshold (an approver may approve any value). `previous_threshold_cents` / `threshold_changed_at` drive the post-change approval cooldown (written ONLY by the set_threshold RPC).
CREATE TABLE IF NOT EXISTS commerce.pur_settings (
    org_id                  UUID PRIMARY KEY,
    approval_threshold_cents BIGINT CHECK (approval_threshold_cents IS NULL OR approval_threshold_cents >= 0),
    previous_threshold_cents BIGINT CHECK (previous_threshold_cents IS NULL OR previous_threshold_cents >= 0),
    threshold_changed_at    TIMESTAMPTZ,
    updated_by              UUID,
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE commerce.pur_settings ADD COLUMN IF NOT EXISTS previous_threshold_cents BIGINT;
ALTER TABLE commerce.pur_settings ADD COLUMN IF NOT EXISTS threshold_changed_at TIMESTAMPTZ;
ALTER TABLE commerce.pur_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pur_settings_select_own_org" ON commerce.pur_settings;
CREATE POLICY "pur_settings_select_own_org" ON commerce.pur_settings FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.pur_settings;
CREATE POLICY "service_role_bypass" ON commerce.pur_settings FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.pur_settings TO authenticated;
GRANT ALL ON commerce.pur_settings TO service_role;

-- Approvers of THIS org (org-scoped: a grant here never reaches another org). Managed by org admins through the set_approver RPC; `can_approve` is membership in this table for the selected org.
CREATE TABLE IF NOT EXISTS commerce.pur_approvers (
    org_id      UUID NOT NULL,
    user_id     UUID NOT NULL,
    granted_by  UUID,
    granted_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (org_id, user_id)
);
ALTER TABLE commerce.pur_approvers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pur_approvers_select_own_org" ON commerce.pur_approvers;
CREATE POLICY "pur_approvers_select_own_org" ON commerce.pur_approvers FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.pur_approvers;
CREATE POLICY "service_role_bypass" ON commerce.pur_approvers FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.pur_approvers TO authenticated;
GRANT ALL ON commerce.pur_approvers TO service_role;

-- Append-only audit of approval-governing changes (threshold changes, approver grants / revocations). UPDATE / DELETE / TRUNCATE are refused by trigger.
CREATE TABLE IF NOT EXISTS commerce.pur_settings_log (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id          UUID NOT NULL,
    kind            TEXT NOT NULL CHECK (kind IN ('threshold', 'approver_added', 'approver_removed')),
    actor_id        UUID,
    subject_user_id UUID,
    old_cents       BIGINT,
    new_cents       BIGINT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_pur_settings_log_org ON commerce.pur_settings_log (org_id, created_at);
CREATE OR REPLACE FUNCTION commerce.pur_settings_log_append_only() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
    RAISE EXCEPTION 'pur_settings_log is append-only' USING ERRCODE = 'insufficient_privilege';
END;
$fn$;
DROP TRIGGER IF EXISTS pur_settings_log_no_update ON commerce.pur_settings_log;
CREATE TRIGGER pur_settings_log_no_update BEFORE UPDATE OR DELETE ON commerce.pur_settings_log
    FOR EACH ROW EXECUTE FUNCTION commerce.pur_settings_log_append_only();
DROP TRIGGER IF EXISTS pur_settings_log_no_truncate ON commerce.pur_settings_log;
CREATE TRIGGER pur_settings_log_no_truncate BEFORE TRUNCATE ON commerce.pur_settings_log
    FOR EACH STATEMENT EXECUTE FUNCTION commerce.pur_settings_log_append_only();
ALTER TABLE commerce.pur_settings_log ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pur_settings_log_select_own_org" ON commerce.pur_settings_log;
CREATE POLICY "pur_settings_log_select_own_org" ON commerce.pur_settings_log FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.pur_settings_log;
CREATE POLICY "service_role_bypass" ON commerce.pur_settings_log FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.pur_settings_log TO authenticated;
GRANT ALL ON commerce.pur_settings_log TO service_role;

-- Per-org sequential order numbers (the counter row is updated inside the save RPC, so a refused save burns no number).
CREATE TABLE IF NOT EXISTS commerce.pur_counters (
    org_id       UUID PRIMARY KEY,
    last_number  INTEGER NOT NULL DEFAULT 0 CHECK (last_number >= 0)
);
