-- Purchase orders. `supplier_name` is the snapshot shown/booked; `party_id` links the parties organ. Totals are computed by the save RPC: total = goods + freight + other - discount.
CREATE TABLE IF NOT EXISTS commerce.pur_orders (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id            UUID NOT NULL,
    number            INTEGER NOT NULL,
    status            TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'approved', 'sent', 'partially_received', 'received', 'cancelled')),
    party_id          UUID,
    supplier_name     TEXT NOT NULL CHECK (btrim(supplier_name) <> ''),
    warehouse_id      UUID REFERENCES commerce.inv_warehouses(id) ON DELETE RESTRICT,
    expected_date     DATE,
    installments_count INTEGER NOT NULL DEFAULT 1 CHECK (installments_count BETWEEN 1 AND 120),
    first_due_days    INTEGER NOT NULL DEFAULT 30 CHECK (first_due_days >= 0),
    interval_days     INTEGER NOT NULL DEFAULT 30 CHECK (interval_days >= 0),
    freight_cents     BIGINT NOT NULL DEFAULT 0 CHECK (freight_cents >= 0),
    discount_cents    BIGINT NOT NULL DEFAULT 0 CHECK (discount_cents >= 0),
    other_cents       BIGINT NOT NULL DEFAULT 0 CHECK (other_cents >= 0),
    goods_cents       BIGINT NOT NULL DEFAULT 0 CHECK (goods_cents >= 0),
    total_cents       BIGINT NOT NULL DEFAULT 0 CHECK (total_cents >= 0),
    notes             TEXT,
    approved_by       UUID,
    approved_at       TIMESTAMPTZ,
    sent_at           TIMESTAMPTZ,
    cancelled_at      TIMESTAMPTZ,
    cancelled_by      UUID,
    cancel_reason     TEXT,
    created_by        UUID,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, org_id),
    UNIQUE (org_id, number),
    CHECK (status <> 'approved' OR approved_at IS NOT NULL),
    FOREIGN KEY (party_id, org_id) REFERENCES commerce.pty_parties(id, org_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_pur_orders_org_status ON commerce.pur_orders (org_id, status, created_at);
CREATE INDEX IF NOT EXISTS idx_pur_orders_party ON commerce.pur_orders (org_id, party_id) WHERE party_id IS NOT NULL;
ALTER TABLE commerce.pur_orders ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pur_orders_select_own_org" ON commerce.pur_orders;
CREATE POLICY "pur_orders_select_own_org" ON commerce.pur_orders FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.pur_orders;
CREATE POLICY "service_role_bypass" ON commerce.pur_orders FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.pur_orders TO authenticated;
GRANT ALL ON commerce.pur_orders TO service_role;

-- Order lines. `received_qty` is maintained by the receive RPC (never above `qty`).
CREATE TABLE IF NOT EXISTS commerce.pur_order_lines (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id           UUID NOT NULL,
    order_id         UUID NOT NULL,
    line_no          INTEGER NOT NULL CHECK (line_no >= 1),
    item_id          UUID REFERENCES commerce.itm_items(id) ON DELETE RESTRICT,
    description      TEXT NOT NULL CHECK (btrim(description) <> ''),
    unit             TEXT,
    qty              NUMERIC(18,3) NOT NULL CHECK (qty > 0),
    unit_cost_cents  BIGINT NOT NULL CHECK (unit_cost_cents >= 0),
    line_total_cents BIGINT NOT NULL CHECK (line_total_cents >= 0),
    received_qty     NUMERIC(18,3) NOT NULL DEFAULT 0,
    UNIQUE (id, org_id),
    UNIQUE (order_id, line_no),
    CONSTRAINT pur_order_lines_received_bounds CHECK (received_qty >= 0 AND received_qty <= qty),
    FOREIGN KEY (order_id, org_id) REFERENCES commerce.pur_orders(id, org_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_pur_order_lines_item ON commerce.pur_order_lines (org_id, item_id) WHERE item_id IS NOT NULL;
ALTER TABLE commerce.pur_order_lines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pur_order_lines_select_own_org" ON commerce.pur_order_lines;
CREATE POLICY "pur_order_lines_select_own_org" ON commerce.pur_order_lines FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.pur_order_lines;
CREATE POLICY "service_role_bypass" ON commerce.pur_order_lines FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.pur_order_lines TO authenticated;
GRANT ALL ON commerce.pur_order_lines TO service_role;

-- Receipts (partial receipts allowed). Amounts are the landed cost computed by the receive RPC (see module docstring); `stock_posted_at` / `finance_posted_at` mark the two idempotent posting legs. `idempotency_key` makes a retried POST a replay.
CREATE TABLE IF NOT EXISTS commerce.pur_receipts (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id                 UUID NOT NULL,
    order_id               UUID NOT NULL,
    receipt_no             INTEGER NOT NULL CHECK (receipt_no >= 1),
    received_on            DATE NOT NULL,
    note                   TEXT,
    goods_cents            BIGINT NOT NULL CHECK (goods_cents >= 0),
    adjustment_cents       BIGINT NOT NULL,
    total_cents            BIGINT NOT NULL CHECK (total_cents >= 0),
    order_goods_before_cents BIGINT NOT NULL CHECK (order_goods_before_cents >= 0),
    idempotency_key        TEXT CHECK (idempotency_key IS NULL OR btrim(idempotency_key) <> ''),
    stock_posted_at        TIMESTAMPTZ,
    finance_posted_at      TIMESTAMPTZ,
    posting_error          TEXT,
    created_by             UUID,
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, org_id),
    UNIQUE (order_id, receipt_no),
    FOREIGN KEY (order_id, org_id) REFERENCES commerce.pur_orders(id, org_id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_pur_receipts_idem ON commerce.pur_receipts (org_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_pur_receipts_org_date ON commerce.pur_receipts (org_id, received_on);
ALTER TABLE commerce.pur_receipts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pur_receipts_select_own_org" ON commerce.pur_receipts;
CREATE POLICY "pur_receipts_select_own_org" ON commerce.pur_receipts FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.pur_receipts;
CREATE POLICY "service_role_bypass" ON commerce.pur_receipts FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.pur_receipts TO authenticated;
GRANT ALL ON commerce.pur_receipts TO service_role;

-- Receipt lines: the quantity received against an order line, its goods value and its prorated share of freight/other/discount; `landed_unit_cost_cents` is what the stock move is booked at.
CREATE TABLE IF NOT EXISTS commerce.pur_receipt_lines (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id                  UUID NOT NULL,
    receipt_id              UUID NOT NULL,
    order_line_id           UUID NOT NULL,
    qty                     NUMERIC(18,3) NOT NULL CHECK (qty > 0),
    unit_cost_cents         BIGINT NOT NULL CHECK (unit_cost_cents >= 0),
    goods_cents             BIGINT NOT NULL CHECK (goods_cents >= 0),
    adjustment_cents        BIGINT NOT NULL,
    landed_unit_cost_cents  BIGINT NOT NULL CHECK (landed_unit_cost_cents >= 0),
    UNIQUE (receipt_id, order_line_id),
    FOREIGN KEY (receipt_id, org_id) REFERENCES commerce.pur_receipts(id, org_id) ON DELETE CASCADE,
    FOREIGN KEY (order_line_id, org_id) REFERENCES commerce.pur_order_lines(id, org_id) ON DELETE RESTRICT
);
ALTER TABLE commerce.pur_receipt_lines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pur_receipt_lines_select_own_org" ON commerce.pur_receipt_lines;
CREATE POLICY "pur_receipt_lines_select_own_org" ON commerce.pur_receipt_lines FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.pur_receipt_lines;
CREATE POLICY "service_role_bypass" ON commerce.pur_receipt_lines FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.pur_receipt_lines TO authenticated;
GRANT ALL ON commerce.pur_receipt_lines TO service_role;

-- Row-locked purchasing writes: lock the ORDER, then write everything in ONE transaction.

DROP FUNCTION IF EXISTS commerce.pur_transition(UUID, UUID, TEXT, UUID, TEXT);

CREATE OR REPLACE FUNCTION commerce.pur_save_order(p_org UUID, p_order_id UUID, p_row JSONB) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    v_code TEXT; v_detail TEXT;
    v_order commerce.pur_orders%ROWTYPE; v_id UUID; v_num INTEGER;
    v_party UUID := NULLIF(p_row->>'party_id', '')::uuid; v_wh UUID := NULLIF(p_row->>'warehouse_id', '')::uuid;
    v_name TEXT := btrim(COALESCE(p_row->>'supplier_name', ''));
    v_freight BIGINT := COALESCE((p_row->>'freight_cents')::bigint, 0);
    v_discount BIGINT := COALESCE((p_row->>'discount_cents')::bigint, 0);
    v_other BIGINT := COALESCE((p_row->>'other_cents')::bigint, 0);
    v_inst INTEGER := COALESCE((p_row->>'installments_count')::integer, 1);
    v_first INTEGER := COALESCE((p_row->>'first_due_days')::integer, 30);
    v_interval INTEGER := COALESCE((p_row->>'interval_days')::integer, 30);
    l JSONB; v_item UUID; v_qty NUMERIC; v_cost BIGINT; v_desc TEXT; v_total BIGINT; v_goods BIGINT := 0; v_no INTEGER := 0;
BEGIN
    IF v_freight < 0 OR v_discount < 0 OR v_other < 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'valor_invalido';
    END IF;
    IF v_inst < 1 OR v_inst > 120 THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'parcelas_invalidas';
    END IF;
    IF v_first < 0 OR v_interval < 0 OR (v_inst > 1 AND v_interval < 1) THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'prazo_invalido';
    END IF;
    IF v_name = '' THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'fornecedor_invalido';
    END IF;
    IF p_row->'lines' IS NULL OR jsonb_typeof(p_row->'lines') <> 'array' OR jsonb_array_length(p_row->'lines') = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'sem_linhas';
    END IF;
    IF v_party IS NOT NULL AND NOT EXISTS (SELECT 1 FROM commerce.pty_parties WHERE id = v_party AND org_id = p_org) THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'fornecedor_invalido';
    END IF;
    IF v_wh IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'deposito_invalido';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM commerce.inv_warehouses WHERE id = v_wh AND org_id = p_org) THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'deposito_invalido';
    END IF;
    IF p_order_id IS NULL THEN
        INSERT INTO commerce.pur_counters (org_id, last_number) VALUES (p_org, 1)
            ON CONFLICT (org_id) DO UPDATE SET last_number = commerce.pur_counters.last_number + 1
            RETURNING last_number INTO v_num;
        INSERT INTO commerce.pur_orders (org_id, number, status, supplier_name, created_by)
            VALUES (p_org, v_num, 'draft', v_name, NULLIF(p_row->>'created_by', '')::uuid) RETURNING id INTO v_id;
    ELSE
        SELECT * INTO v_order FROM commerce.pur_orders WHERE id = p_order_id AND org_id = p_org FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_inexistente';
        END IF;
        IF v_order.status <> 'draft' THEN
            RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_nao_editavel';
        END IF;
        v_id := v_order.id;
        DELETE FROM commerce.pur_order_lines WHERE order_id = v_id AND org_id = p_org;
    END IF;
    FOR l IN SELECT * FROM jsonb_array_elements(p_row->'lines') LOOP
        v_no := v_no + 1;
        v_item := NULLIF(l->>'item_id', '')::uuid;
        v_qty := (l->>'qty')::numeric;
        v_cost := (l->>'unit_cost_cents')::bigint;
        v_desc := btrim(COALESCE(l->>'description', ''));
        IF v_qty IS NULL OR v_qty <= 0 THEN
            RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'quantidade_invalida';
        END IF;
        IF v_cost IS NULL OR v_cost < 0 OR v_desc = '' THEN
            RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'linha_invalida';
        END IF;
        IF v_item IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'item_obrigatorio';
        END IF;
        IF v_item IS NOT NULL AND NOT EXISTS (SELECT 1 FROM commerce.itm_items WHERE id = v_item AND org_id = p_org) THEN
            RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'item_invalido';
        END IF;
        v_total := round(v_qty * v_cost)::bigint;
        v_goods := v_goods + v_total;
        INSERT INTO commerce.pur_order_lines (org_id, order_id, line_no, item_id, description, unit, qty, unit_cost_cents, line_total_cents)
            VALUES (p_org, v_id, v_no, v_item, v_desc, NULLIF(l->>'unit', ''), v_qty, v_cost, v_total);
    END LOOP;
    IF v_goods <= 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_sem_valor';
    END IF;
    IF v_goods + v_freight + v_other - v_discount < 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'desconto_excede';
    END IF;
    UPDATE commerce.pur_orders SET party_id = v_party, supplier_name = v_name, warehouse_id = v_wh,
        expected_date = NULLIF(p_row->>'expected_date', '')::date, installments_count = v_inst,
        first_due_days = v_first, interval_days = v_interval, freight_cents = v_freight, discount_cents = v_discount,
        other_cents = v_other, goods_cents = v_goods, total_cents = v_goods + v_freight + v_other - v_discount,
        notes = NULLIF(btrim(COALESCE(p_row->>'notes', '')), ''), updated_at = now()
        WHERE id = v_id AND org_id = p_org;
    RETURN jsonb_build_object('status', 'ok', 'order_id', v_id);
EXCEPTION WHEN SQLSTATE 'PU001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'order_line_id', NULLIF(v_detail, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.pur_save_order(UUID, UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.pur_save_order(UUID, UUID, JSONB) TO service_role;

CREATE OR REPLACE FUNCTION commerce.pur_transition(p_org UUID, p_order_id UUID, p_action TEXT, p_user UUID, p_reason TEXT, p_actor_can_exceed BOOLEAN DEFAULT false) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    v_code TEXT; v_detail TEXT; v_order commerce.pur_orders%ROWTYPE; v_target TEXT; v_from TEXT[];
    v_thr BIGINT; v_prev BIGINT; v_chg TIMESTAMPTZ; v_low BIGINT;
BEGIN
    SELECT * INTO v_order FROM commerce.pur_orders WHERE id = p_order_id AND org_id = p_org FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_inexistente';
    END IF;
    IF p_action = 'approve' THEN v_target := 'approved'; v_from := ARRAY['draft'];
    ELSIF p_action = 'send' THEN v_target := 'sent'; v_from := ARRAY['approved'];
    ELSIF p_action = 'cancel' THEN v_target := 'cancelled'; v_from := ARRAY['draft', 'approved', 'sent'];
    ELSE
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'transicao_invalida';
    END IF;
    IF v_order.status = v_target THEN
        RETURN jsonb_build_object('status', 'replayed', 'order_id', v_order.id);
    END IF;
    IF p_action = 'cancel' AND EXISTS (SELECT 1 FROM commerce.pur_receipts WHERE order_id = v_order.id AND org_id = p_org) THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_com_recebimento';
    END IF;
    IF NOT (v_order.status = ANY (v_from)) THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'transicao_invalida';
    END IF;
    IF p_action = 'approve' THEN
        -- The limit is judged HERE, under the order's row lock, against the order's CURRENT total (a concurrent PUT that
        -- raised it has either committed before this lock was taken or waits for it); the threshold row is share-locked
        -- so a concurrent threshold change cannot slip between the read and the write.
        SELECT approval_threshold_cents, previous_threshold_cents, threshold_changed_at INTO v_thr, v_prev, v_chg
            FROM commerce.pur_settings WHERE org_id = p_org FOR SHARE;
        IF FOUND THEN
            IF v_thr IS NOT NULL AND v_order.total_cents > v_thr AND NOT COALESCE(p_actor_can_exceed, false) THEN
                RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'aprovacao_acima_do_limite';
            END IF;
            IF v_chg IS NOT NULL AND v_chg > now() - interval '10 minutes' THEN
                v_low := LEAST(COALESCE(v_thr, 9223372036854775807), COALESCE(v_prev, 9223372036854775807));
                IF v_order.total_cents > v_low THEN
                    RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'limite_em_carencia';
                END IF;
            END IF;
        END IF;
        UPDATE commerce.pur_orders SET status = 'approved', approved_by = p_user, approved_at = now(), updated_at = now() WHERE id = v_order.id;
    ELSIF p_action = 'send' THEN
        UPDATE commerce.pur_orders SET status = 'sent', sent_at = now(), updated_at = now() WHERE id = v_order.id;
    ELSE
        UPDATE commerce.pur_orders SET status = 'cancelled', cancelled_at = now(), cancelled_by = p_user,
            cancel_reason = NULLIF(btrim(COALESCE(p_reason, '')), ''), updated_at = now() WHERE id = v_order.id;
    END IF;
    RETURN jsonb_build_object('status', 'ok', 'order_id', v_order.id);
EXCEPTION WHEN SQLSTATE 'PU001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'order_line_id', NULLIF(v_detail, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.pur_transition(UUID, UUID, TEXT, UUID, TEXT, BOOLEAN) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.pur_transition(UUID, UUID, TEXT, UUID, TEXT, BOOLEAN) TO service_role;

CREATE OR REPLACE FUNCTION commerce.pur_receive(p_org UUID, p_order_id UUID, p_row JSONB) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    v_code TEXT; v_detail TEXT;
    v_order commerce.pur_orders%ROWTYPE; v_prev commerce.pur_receipts%ROWTYPE; v_ol commerce.pur_order_lines%ROWTYPE; v_rid UUID := gen_random_uuid();
    v_key TEXT := NULLIF(btrim(COALESCE(p_row->>'idempotency_key', '')), '');
    l RECORD;
    v_before BIGINT; v_a BIGINT; v_g BIGINT; v_rgoods BIGINT := 0; v_radj BIGINT; v_no INTEGER;
    v_cum BIGINT := 0; v_prev_share BIGINT := 0; v_share BIGINT; v_adj BIGINT; v_goods BIGINT; v_landed BIGINT;
    v_open INTEGER; v_status TEXT;
BEGIN
    SELECT * INTO v_order FROM commerce.pur_orders WHERE id = p_order_id AND org_id = p_org FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_inexistente';
    END IF;
    IF v_key IS NOT NULL THEN
        SELECT * INTO v_prev FROM commerce.pur_receipts WHERE org_id = p_org AND idempotency_key = v_key;
        IF FOUND THEN
            IF v_prev.order_id <> v_order.id THEN
                RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'chave_reutilizada';
            END IF;
            RETURN jsonb_build_object('status', 'replayed', 'receipt_id', v_prev.id, 'order_status', v_order.status);
        END IF;
    END IF;
    IF v_order.status = 'received' THEN RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_ja_recebido';
    ELSIF v_order.status = 'cancelled' THEN RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_cancelado';
    ELSIF v_order.status = 'draft' THEN RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_nao_aprovado';
    ELSIF v_order.status NOT IN ('approved', 'sent', 'partially_received') THEN RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'pedido_nao_recebivel';
    END IF;
    IF p_row->'lines' IS NULL OR jsonb_typeof(p_row->'lines') <> 'array' OR jsonb_array_length(p_row->'lines') = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'sem_linhas';
    END IF;
    SELECT COALESCE(SUM(rl.goods_cents), 0) INTO v_before FROM commerce.pur_receipt_lines rl
        JOIN commerce.pur_receipts r ON r.id = rl.receipt_id AND r.org_id = rl.org_id WHERE r.order_id = v_order.id AND r.org_id = p_org;
    SELECT COALESCE(MAX(receipt_no), 0) + 1 INTO v_no FROM commerce.pur_receipts WHERE order_id = v_order.id;
    v_a := v_order.freight_cents + v_order.other_cents - v_order.discount_cents;
    v_g := v_order.goods_cents;
    -- First pass: validate + total this receipt's goods (grouped by order line) under the lock.
    FOR l IN
        SELECT (x->>'order_line_id')::uuid AS order_line_id, sum((x->>'qty')::numeric) AS qty
        FROM jsonb_array_elements(p_row->'lines') x GROUP BY 1
    LOOP
        SELECT * INTO v_ol FROM commerce.pur_order_lines WHERE id = l.order_line_id AND order_id = v_order.id AND org_id = p_org FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'linha_invalida', DETAIL = l.order_line_id::text;
        END IF;
        IF l.qty IS NULL OR l.qty <= 0 THEN
            RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'quantidade_invalida', DETAIL = l.order_line_id::text;
        END IF;
        IF v_ol.received_qty + l.qty > v_ol.qty THEN
            RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'recebimento_excede_pedido', DETAIL = l.order_line_id::text;
        END IF;
        v_rgoods := v_rgoods + round(l.qty * v_ol.unit_cost_cents)::bigint;
    END LOOP;
    v_radj := round((v_a * (v_before + v_rgoods))::numeric / v_g)::bigint - round((v_a * v_before)::numeric / v_g)::bigint;
    INSERT INTO commerce.pur_receipts (id, org_id, order_id, receipt_no, received_on, note, goods_cents, adjustment_cents, total_cents,
                            order_goods_before_cents, idempotency_key, created_by)
        VALUES (v_rid, p_org, v_order.id, v_no, COALESCE(NULLIF(p_row->>'received_on', '')::date, CURRENT_DATE),
                NULLIF(btrim(COALESCE(p_row->>'note', '')), ''), v_rgoods, v_radj, v_rgoods + v_radj, v_before, v_key,
                NULLIF(p_row->>'created_by', '')::uuid);
    -- Second pass: per-line landed cost by cumulative proration (telescopes to exactly v_radj).
    FOR l IN
        SELECT (x->>'order_line_id')::uuid AS order_line_id, sum((x->>'qty')::numeric) AS qty, ol.line_no
        FROM jsonb_array_elements(p_row->'lines') x JOIN commerce.pur_order_lines ol ON ol.id = (x->>'order_line_id')::uuid
        GROUP BY 1, ol.line_no ORDER BY ol.line_no
    LOOP
        SELECT * INTO v_ol FROM commerce.pur_order_lines WHERE id = l.order_line_id;
        v_goods := round(l.qty * v_ol.unit_cost_cents)::bigint;
        v_cum := v_cum + v_goods;
        v_share := CASE WHEN v_rgoods = 0 THEN 0 ELSE round((v_radj * v_cum)::numeric / v_rgoods)::bigint END;
        v_adj := v_share - v_prev_share;
        v_prev_share := v_share;
        v_landed := GREATEST(0, round((v_goods + v_adj)::numeric / l.qty)::bigint);
        INSERT INTO commerce.pur_receipt_lines (org_id, receipt_id, order_line_id, qty, unit_cost_cents, goods_cents, adjustment_cents, landed_unit_cost_cents)
            VALUES (p_org, v_rid, l.order_line_id, l.qty, v_ol.unit_cost_cents, v_goods, v_adj, v_landed);
        UPDATE commerce.pur_order_lines SET received_qty = received_qty + l.qty WHERE id = l.order_line_id;
    END LOOP;
    SELECT count(*) INTO v_open FROM commerce.pur_order_lines WHERE order_id = v_order.id AND received_qty < qty;
    v_status := CASE WHEN v_open = 0 THEN 'received' ELSE 'partially_received' END;
    UPDATE commerce.pur_orders SET status = v_status, updated_at = now() WHERE id = v_order.id;
    RETURN jsonb_build_object('status', 'ok', 'receipt_id', v_rid, 'order_status', v_status);
EXCEPTION WHEN SQLSTATE 'PU001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'order_line_id', NULLIF(v_detail, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.pur_receive(UUID, UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.pur_receive(UUID, UUID, JSONB) TO service_role;

CREATE OR REPLACE FUNCTION commerce.pur_set_threshold(p_org UUID, p_user UUID, p_cents BIGINT) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    v_code TEXT; v_detail TEXT; v_row commerce.pur_settings%ROWTYPE; v_prev BIGINT;
BEGIN
    IF p_cents IS NOT NULL AND p_cents < 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'valor_invalido';
    END IF;
    INSERT INTO commerce.pur_settings (org_id) VALUES (p_org) ON CONFLICT (org_id) DO NOTHING;
    SELECT * INTO v_row FROM commerce.pur_settings WHERE org_id = p_org FOR UPDATE;
    IF v_row.approval_threshold_cents IS NOT DISTINCT FROM p_cents THEN
        RETURN jsonb_build_object('status', 'replayed');
    END IF;
    IF v_row.threshold_changed_at IS NOT NULL AND v_row.threshold_changed_at > now() - interval '10 minutes' THEN
        v_prev := NULLIF(LEAST(COALESCE(v_row.previous_threshold_cents, 9223372036854775807), COALESCE(v_row.approval_threshold_cents, 9223372036854775807)), 9223372036854775807);
    ELSE
        v_prev := v_row.approval_threshold_cents;
    END IF;
    UPDATE commerce.pur_settings SET approval_threshold_cents = p_cents, previous_threshold_cents = v_prev,
        threshold_changed_at = now(), updated_by = p_user, updated_at = now() WHERE org_id = p_org;
    INSERT INTO commerce.pur_settings_log (org_id, kind, actor_id, old_cents, new_cents)
        VALUES (p_org, 'threshold', p_user, v_row.approval_threshold_cents, p_cents);
    RETURN jsonb_build_object('status', 'ok');
EXCEPTION WHEN SQLSTATE 'PU001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'order_line_id', NULLIF(v_detail, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.pur_set_threshold(UUID, UUID, BIGINT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.pur_set_threshold(UUID, UUID, BIGINT) TO service_role;

CREATE OR REPLACE FUNCTION commerce.pur_set_approver(p_org UUID, p_actor UUID, p_user UUID, p_grant BOOLEAN) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    v_code TEXT; v_detail TEXT; v_n INTEGER;
BEGIN
    IF p_user IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'PU001', MESSAGE = 'usuario_invalido';
    END IF;
    IF COALESCE(p_grant, false) THEN
        INSERT INTO commerce.pur_approvers (org_id, user_id, granted_by) VALUES (p_org, p_user, p_actor) ON CONFLICT (org_id, user_id) DO NOTHING;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n = 0 THEN
            RETURN jsonb_build_object('status', 'replayed');
        END IF;
        INSERT INTO commerce.pur_settings_log (org_id, kind, actor_id, subject_user_id) VALUES (p_org, 'approver_added', p_actor, p_user);
    ELSE
        DELETE FROM commerce.pur_approvers WHERE org_id = p_org AND user_id = p_user;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n = 0 THEN
            RETURN jsonb_build_object('status', 'replayed');
        END IF;
        INSERT INTO commerce.pur_settings_log (org_id, kind, actor_id, subject_user_id) VALUES (p_org, 'approver_removed', p_actor, p_user);
    END IF;
    RETURN jsonb_build_object('status', 'ok');
EXCEPTION WHEN SQLSTATE 'PU001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'order_line_id', NULLIF(v_detail, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.pur_set_approver(UUID, UUID, UUID, BOOLEAN) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.pur_set_approver(UUID, UUID, UUID, BOOLEAN) TO service_role;
